 */
class Chats extends ApiResource
{
    /**
     * List chatbot conversations.
     *
     * Lists the club chatbot conversations (website visitor ↔ bot) over a date range
     * (defaults to the last 7 days), newest first. Only public website-chatbot conversations
     * are returned, never the internal staff assistant.
     *
     * GET /chats responds with ChatConversation[].
     *
     * @param  DateTimeInterface|string|null  $from  Start date (YYYY-MM-DD). Defaults to 7 days ago.
     * @param  DateTimeInterface|string|null  $to  End date (YYYY-MM-DD). Defaults to today.
     * @param  ?int  $clubId  Conversations of this club. Omit (or 0) for the current club. With a club-limited key, omitting it (or 0/-1) means the key's club; another club returns 403.
     * @return list<array<string, mixed>>
     *
     * @throws ClubPlannerException
     */
    public function list(DateTimeInterface|string|null $from = null, DateTimeInterface|string|null $to = null, ?int $clubId = null): array
    {
        return $this->transport->get('chats', [
            'from' => $this->date($from),
            'to' => $this->date($to),
            'clubId' => $clubId,
        ]);
    }

    /**
     * Get a chatbot conversation.
     *
     * Returns a full chatbot conversation: the message bubbles between the visitor and the
     * bot. Internal tool calls are stripped — only the visitor-facing text is returned.
     *
     * GET /chats/{conversationId} responds with ChatConversationDetail.
     *
     * @param  string  $conversationId  The conversation id (from the list endpoint).
     * @return array<string, mixed>
     *
     * @throws ClubPlannerException
     */
    public function get(string $conversationId): array
    {
        return $this->transport->get('chats/'.rawurlencode($conversationId));
    }
}
